# System.Runtime.Intrinsics.X86.Avx512F.VL — the 128- and 256-bit forms of the instructions
# Avx512F adds below the Sse / Avx surface: 64-bit Abs, Max and Min, the float exponent and
# mantissa extractors, the 14-bit reciprocal estimates (approximations, no reference),
# RoundScale, Scale and Fixup. The token requires the whole .NET 10 AVX-512 unit (see
# avx512f/arithmetic.map), so the helpers compile for it.
target = avx512f,avx512bw,avx512dq,avx512vl
Abs(v{W}i64) @ref(Vector{W}.Abs($0).AsUInt64()) = {mm}_abs_epi64($0) for W in 128,256
Max(v{W}{T},v{W}{T}) @ref(Vector{W}.Max($0, $1)) = {mm}_max_{ep}($0, $1) for W in 128,256 for T in i64,u64
Min(v{W}{T},v{W}{T}) @ref(Vector{W}.Min($0, $1)) = {mm}_min_{ep}($0, $1) for W in 128,256 for T in i64,u64
Reciprocal14(v{W}{T}) = {mm}_rcp14_{ps|pd}($0) for W in 128,256 for T in f32,f64
ReciprocalSqrt14(v{W}{T}) = {mm}_rsqrt14_{ps|pd}($0) for W in 128,256 for T in f32,f64
Scale(v{W}{T},v{W}{T}) = {mm}_scalef_{ps|pd}($0, $1) for W in 128,256 for T in f32,f64
GetExponent(v{W}{T}) = {mm}_getexp_{ps|pd}($0) for W in 128,256 for T in f32,f64
GetMantissa(v{W}{T},u8) @imm[0..16) = {mm}_getmant_{ps|pd}($0, (_MM_MANTISSA_NORM_ENUM)($1 & 3), (_MM_MANTISSA_SIGN_ENUM)($1 >> 2)) for W in 128,256 for T in f32,f64
RoundScale(v{W}{T},u8) @imm8 = {mm}_roundscale_{ps|pd}($0, $1) for W in 128,256 for T in f32,f64
Fixup(v{W}{T},v{W}{T},v{W}{sT},u8) @imm8 = {mm}_fixupimm_{ps|pd}($0, $1, $2, $3) for W in 128,256 for T in f32,f64
